import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    """Calculate desirability score for each candidate swath."""
    # Base desirability: strongly prefer short transit distances
    dist_score = 1.0 / (dist_m + 1e-4)

    # Turn cost is secondary to distance but still relevant; use inverse relationship
    turn_score = 1.0 / (turn_deg + 1e-4)

    # Energy safety: when battery is low (<0.2), strongly prefer swaths ending near depot; 
    # otherwise, slightly penalize long swaths that might consume too much energy relative to remaining capacity.
    # We use a linear drop-off for the penalty based on swath length and energy fraction.
    if fits == 0.0:
        # Infeasible move: assign extremely low but finite positive score to allow exploration
        return np.full_like(dist_score, 1e-6, dtype=float)

    safety_factor = 1.0
    if energy_left_frac < 0.25:
        # Prefer depot returns when battery is critically low
        safety_factor = 1.0 / (depot_dist_m + 1e-4) / (dist_m + 1e-4) * 5.0
    else:
        # Normal operation: slight preference for shorter swaths to conserve energy margin
        safety_factor = 1.0 - 0.1 * swath_len_m * (1.0 - energy_left_frac)

    return np.maximum(1e-6, dist_score * turn_score * safety_factor)
